    pos = defaultdict(list)
    for i in range(n):
        for j in range(m):
            pos[grid[i][j]].append((i, j))

    # bipartition: color by (i+j)%2
    color = [[(i + j) & 1 for j in range(m)] for i in range(n)]

    # build graph: nodes are shoe numbers, edges between numbers whose cells are adjacent
    adj = defaultdict(set)

    # map from cell to shoe number
    # already grid

    for i in range(n):
        for j in range(m):
            u = grid[i][j]
            for di, dj in ((1, 0), (0, 1)):
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < m:
                    v = grid[ni][nj]
                    if u != v:
                        adj[u].add(v)
                        adj[v].add(u)

    # we need maximum matching on this graph, but only between nodes whose two cells
    # are of opposite colors (otherwise they can never be adjacent in final grid)
    # However, edges already correspond to adjacency in grid, which always connects opposite colors.
    # So graph is bipartite by construction.

    # Build bipartite sets: left = numbers whose first occurrence is on black (0), right otherwise
    left_nodes = []
    right_nodes = []
    side = {}
    for num, cells in pos.items():
        # any cell defines side; both cells have opposite colors, but we assign node to side of first cell
        i, j = cells[0]
        if color[i][j] == 0:
            side[num] = 0
            left_nodes.append(num)
        else:
            side[num] = 1
            right_nodes.append(num)

    # Build adjacency for left side only
    left_adj = {u: [] for u in left_nodes}
    for u in left_nodes:
        for v in adj[u]:
            if v in side and side[v] == 1:
                left_adj[u].append(v)

    # Hopcroft-Karp
    INF = 10**18
    pair_u = {}
    pair_v = {}
    dist = {}

    def bfs():
        q = deque()
        for u in left_nodes:
            if u not in pair_u:
                dist[u] = 0
                q.append(u)
            else:
                dist[u] = INF
        d_inf = INF
        while q:
            u = q.popleft()
            if dist[u] < d_inf:
                for v in left_adj[u]:
                    pu = pair_v.get(v)
                    if pu is None:
                        d_inf = dist[u] + 1
                    else:
                        if dist[pu] == INF:
                            dist[pu] = dist[u] + 1
                            q.append(pu)
        return d_inf != INF

    def dfs(u):
        for v in left_adj[u]:
            pu = pair_v.get(v)
            if pu is None or (dist[pu] == dist[u] + 1 and dfs(pu)):
                pair_u[u] = v
                pair_v[v] = u
                return True
        dist[u] = INF
        return False

    matching = 0
    while bfs():
        for u in left_nodes:
            if u not in pair_u:
                if dfs(u):
                    matching += 1

    # Each matched pair of shoe numbers corresponds to 2 shoes already adjacent.
    # Total shoes = n*m. Each matched pair saves moving 2 shoes.
    # We need to place all pairs; unmatched pairs require moving both shoes.
    # Minimum moved shoes = total shoes - 2 * matching
    total_shoes = n * m
    result = total_shoes - 2 * matching
    print(result)

